class Counter:

    def __init__(self):
        self.count = 0

    def __iter__(self):
        return self

    def __next__(self):
        if self.count >= 3:
            raise StopIteration
        self.count += 1
        return self.count

    def __enter__(self):
        return self

    def __exit__(self, *args):
        pass

def counter():
    counter.value += 1
    if counter.value > 3:
        raise StopIteration
    return counter.value

